```cpp
#include <iostream>
#include <string>

class Animal {
protected:
    std::string name_;
public:
    Animal(const std::string& n) : name_(n) {}
    virtual ~Animal() = default; // 多态基类必备虚析构
    virtual void speak() const { std::cout << name_ << " ?\n"; }
    const std::string& name() const { return name_; }
};

class Dog : public Animal {
public:
    Dog(const std::string& n) : Animal(n) {}
    void speak() const override { std::cout << name_ << ": 汪汪\n"; }
};

class Cat : public Animal {
public:
    Cat(const std::string& n) : Animal(n) {}
    void speak() const override { std::cout << name_ << ": 喵喵\n"; }
};

void let_it_speak(const Animal& a) { a.speak(); }

int main() {
    Dog d("旺财");
    Cat c("小花");
    let_it_speak(d); // 实际调用 Dog::speak
    let_it_speak(c); // 实际调用 Cat::speak
}
