Shape作为抽象接口定义契约，Circle和Rectangle实现具体公式；调用方通过基类指针操作，自动调用对应派生实现。
```cpp
#include <iostream>
#include <cmath>
#include <memory>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual double perimeter() const = 0;
};

class Circle : public Shape {
    double r_;
public:
    explicit Circle(double r) : r_(r) {}
    double area() const override { return M_PI * r_ * r_; }
    double perimeter() const override { return 2 * M_PI * r_; }
};

class Rectangle : public Shape {
    double w_, h_;
public:
    Rectangle(double w, double h) : w_(w), h_(h) {}
    double area() const override { return w_ * h_; }
    double perimeter() const override { return 2 * (w_ + h_); }
};

void print_info(const Shape* s) {
    std::cout << "area=" << s->area()
              << " perimeter=" << s->perimeter() << '\n';
}

int main() {
    std::unique_ptr<Shape> a = std::make_unique<Circle>(2.0);
    std::unique_ptr<Shape> b = std::make_unique<Rectangle>(3.0, 4.0);
    print_info(a.get());
    print_info(b.get());
}
