模板方法模式：基类封装不变流程，派生类实现变化步骤。
```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <numeric>

class DataMiner {
    std::string path_;
public:
    explicit DataMiner(std::string p) : path_(std::move(p)) {}
    virtual ~DataMiner() = default;

    void mine() {
        auto raw = openFile(path_);
        auto lines = extractData(raw);
        auto data = parseData(lines);
        auto report = analyzeData(data);
        sendReport(report);
    }
protected:
    virtual std::string openFile(const std::string& p) = 0;
    virtual std::vector<std::string> extractData(const std::string&) = 0;
    virtual std::vector<double> parseData(const std::vector<std::string>&) = 0;
    virtual double analyzeData(const std::vector<double>&) = 0;
    virtual void sendReport(double r) = 0;
};

class CSVDataMiner : public DataMiner {
public:
    using DataMiner::DataMiner;
protected:
    std::string openFile(const std::string& p) override {
        std::ifstream f(p); std::stringstream ss; ss << f.rdbuf();
        return ss.str();
    }
    std::vector<std::string> extractData(const std::string& s) override {
        std::vector<std::string> out; std::istringstream iss(s);
        for (std::string line; std::getline(iss, line);) out.push_back(line);
        return out;
    }
    std::vector<double> parseData(const std::vector<std::string>& lines) override {
        std::vector<double> v; for (auto& l : lines) v.push_back(std::stod(l));
        return v;
    }
    double analyzeData(const std::vector<double>& data) override {
        return std::accumulate(data.begin(), data.end(), 0.0);
    }
    void sendReport(double r) override { std::cout << "report=" << r << '\n'; }
};
```

用友元让受控的迭代器类访问容器私有数据，再用const重载表达只读视图。
```cpp
#include <iostream>
#include <vector>

template<typename T> class Container {
    std::vector<T> data_;
public:
    void push_back(const T& v) { data_.push_back(v); }
    std::size_t size() const { return data_.size(); }

    class iterator {
        T* p_;
    public:
        explicit iterator(T* p) : p_(p) {}
        T& operator*() const { return *p_; }
        iterator& operator++() { ++p_; return *this; }
        bool operator!=(const iterator& o) const { return p_ != o.p_; }
        friend class Container;
    };
    iterator begin() { return iterator(data_.data()); }
    iterator end()   { return iterator(data_.data() + data_.size()); }

    class const_iterator {
        const T* p_;
    public:
        explicit const_iterator(const T* p) : p_(p) {}
        const T& operator*() const { return *p_; }
        const_iterator& operator++() { ++p_; return *this; }
        bool operator!=(const const_iterator& o) const { return p_ != o.p_; }
        friend class Container;
    };
    const_iterator begin() const { return const_iterator(data_.data()); }
    const_iterator end()   const { return const_iterator(data_.data()+data_.size()); }
};

int main() {
    Container<int> c; for (int i=0;i<3;++i) c.push_back(i);
    for (auto& x : c) std::cout << x;
    const auto& cc = c;
    for (auto& x : cc) std::cout << x;
}
```

用CRTP让基类在编译期通过static_cast恢复派生类型，实现零开销的静态多态。
```cpp
#include <iostream>

template<typename Derived>
class Addable {
public:
    Derived operator+(const Derived& rhs) const {
        Derived lhs = static_cast<const Derived*>(this)->clone();
        lhs.add_in_place(rhs);
        return lhs;
    }
};

template<typename Derived>
class Scalable {
public:
    Derived operator*(double k) const {
        Derived lhs = static_cast<const Derived*>(this)->clone();
        lhs.scale_in_place(k);
        return lhs;
    }
};

class Vec2 : public Addable<Vec2>, public Scalable<Vec2> {
    double x_, y_;
public:
    Vec2(double x=0, double y=0) : x_(x), y_(y) {}
    Vec2 clone() const { return *this; }
    void add_in_place(const Vec2& r) { x_+=r.x_; y_+=r.y_; }
    void scale_in_place(double k) { x_*=k; y_*=k; }
    void print() const { std::cout << '(' << x_ << ',' << y_ << ")\n"; }
};

int main() {
    Vec2 a(1,2), b(3,4);
    Vec2 c = a + b;
    Vec2 d = c * 2.0;
    d.print();
}
```

