类模板参数化类型T和非类型参数N，内部用std::array保证栈容量固定。
```cpp
#include <array>
#include <stdexcept>
#include <iostream>

template<typename T, std::size_t N>
class Stack {
    std::array<T, N> data_{};
    std::size_t size_ = 0;
public:
    void push(const T& v) {
        if (size_ == N) throw std::runtime_error("stack full");
        data_[size_++] = v;
    }
    void pop() {
        if (size_ == 0) throw std::runtime_error("stack empty");
        --size_;
    }
    T& top() { return data_[size_-1]; }
    const T& top() const { return data_[size_-1]; }
    std::size_t size()  const { return size_; }
    bool empty() const { return size_ == 0; }
};

int main() {
    Stack<int, 3> s;
    s.push(1); s.push(2); s.push(3);
    try { s.push(4); } catch (const std::exception& e) { std::cout << e.what() << '\n'; }
    std::cout << s.top() << ' ' << s.size() << '\n';
}
