主模板处理算术类型，显式特化处理std::string和std::pair。
```cpp
#include <cstddef>
#include <string>
#include <utility>
#include <type_traits>

struct FNV1a {
    std::size_t operator()(const std::string& s) const noexcept {
        std::size_t h = 1469598103934665603ull;
        for (unsigned char c : s) { h ^= c; h *= 1099511628211ull; }
        return h;
    }
};

template<typename T, typename = void> struct Hash;

template<typename T>
struct Hash<T, std::enable_if_t<std::is_arithmetic_v<T>>> {
    std::size_t operator()(T v) const noexcept { return static_cast<std::size_t>(v); }
};

template<> struct Hash<std::string> {
    FNV1a fnv;
    std::size_t operator()(const std::string& s) const noexcept { return fnv(s); }
};

template<> struct Hash<std::pair<int,int>> {
    std::size_t operator()(const std::pair<int,int>& p) const noexcept {
        return (static_cast<std::size_t>(p.first) << 16)
             ^ static_cast<std::size_t>(p.second);
    }
};
