RAII三要素：构造获取、析构释放、禁用拷贝。移动语义允许所有权转移。
```cpp
#include <cstdio>
#include <string>
#include <utility>
#include <iostream>

class FileGuard {
    FILE* fp_ = nullptr;
public:
    explicit FileGuard(const std::string& path, const char* mode) {
        fp_ = std::fopen(path.c_str(), mode);
        if (!fp_) throw std::runtime_error("open failed");
    }
    ~FileGuard() { if (fp_) std::fclose(fp_); }

    FileGuard(const FileGuard&)            = delete;
    FileGuard& operator=(const FileGuard&) = delete;

    FileGuard(FileGuard&& o) noexcept : fp_(o.fp_) { o.fp_ = nullptr; }
    FileGuard& operator=(FileGuard&& o) noexcept {
        if (this != &o) {
            if (fp_) std::fclose(fp_);
            fp_ = o.fp_; o.fp_ = nullptr;
        }
        return *this;
    }
    void write(const std::string& s) { std::fputs(s.c_str(), fp_); }
};

int main() {
    FileGuard f("out.txt", "w");
    f.write("RAII demo\n");
}
