亲手实现unique_ptr核心功能，加深对RAII与禁用拷贝的理解。
```cpp
#include <iostream>

template<typename T>
class SmartPtr {
    T* p_ = nullptr;
public:
    SmartPtr() = default;
    explicit SmartPtr(T* p) : p_(p) {}
    ~SmartPtr() { delete p_; }

    SmartPtr(const SmartPtr&)            = delete;
    SmartPtr& operator=(const SmartPtr&) = delete;

    SmartPtr(SmartPtr&& o) noexcept : p_(o.p_) { o.p_ = nullptr; }
    SmartPtr& operator=(SmartPtr&& o) noexcept {
        if (this != &o) { delete p_; p_ = o.p_; o.p_ = nullptr; }
        return *this;
    }
    T& operator*()  const { return *p_; }
    T* operator->() const { return p_;  }
    T* get()        const { return p_;  }
    void reset(T* np = nullptr) { delete p_; p_ = np; }
};

struct Foo { void hello() { std::cout << "hi\n"; } };

int main() {
    SmartPtr<Foo> sp(new Foo);
    sp->hello();
    (*sp).hello();
}
