```cpp
#include <iostream>

class Complex {
    double re_, im_;
public:
    Complex(double r=0, double i=0) : re_(r), im_(i) {}
    double real() const { return re_; } double imag() const { return im_; }

    friend Complex operator+(Complex a, const Complex& b) { return {a.re_+b.re_, a.im_+b.im_}; }
    friend Complex operator-(Complex a, const Complex& b) { return {a.re_-b.re_, a.im_-b.im_}; }
    friend Complex operator*(Complex a, const Complex& b) {
        return {a.re_*b.re_ - a.im_*b.im_, a.re_*b.im_ + a.im_*b.re_};
    }
    friend bool operator==(const Complex& a, const Complex& b) {
        return a.re_==b.re_ && a.im_==b.im_;
    }
    friend std::ostream& operator<<(std::ostream& os, const Complex& c) {
        return os << '(' << c.re_ << ',' << c.im_ << ')';
    }
};

int main() {
    Complex a(1,2), b(3,4);
    std::cout << a+b << ' ' << a*b << ' ' << (a==b) << '\n';
}
```

用vector按位存储+竖式算法，重载运算符让大数用起来像内建类型。
```cpp
#include <vector>
#include <iostream>
#include <algorithm>

class BigInt {
    std::vector<int> d_; // 低位在前
public:
    BigInt() = default;
    explicit BigInt(long long n) { while (n>0) { d_.push_back(n%10); n/=10; } }
    bool isZero() const { return d_.empty(); }

    friend BigInt operator+(BigInt a, const BigInt& b) {
        BigInt c; int carry = 0;
        std::size_t n = std::max(a.d_.size(), b.d_.size());
        c.d_.resize(n);
        for (std::size_t i=0;i<n;++i) {
            int s = carry + (i<a.d_.size()?a.d_[i]:0) + (i<b.d_.size()?b.d_[i]:0);
            c.d_[i] = s%10; carry = s/10;
        }
        if (carry) c.d_.push_back(carry);
        return c;
    }
    friend std::ostream& operator<<(std::ostream& os, const BigInt& x) {
        if (x.d_.empty()) return os << 0;
        for (auto it=x.d_.rbegin(); it!=x.d_.rend(); ++it) os << *it;
        return os;
    }
};

int main() {
    BigInt a(12345), b(6789);
    std::cout << a + b << '\n';
}
```

