#include <iostream>
#include <string>

class AppError : public std::exception {
public:
    virtual int code() const = 0;
};

class NetworkError : public AppError {
    std::string host_;
public:
    explicit NetworkError(std::string h) : host_(std::move(h)) {}
    int code() const override { return 1001; }
    const char* what() const noexcept override { return "network error"; }
    const std::string& host() const { return host_; }
};

class FileError : public AppError {
public:
    int code() const override { return 2001; }
    const char* what() const noexcept override { return "file error"; }
};

