noexcept是承诺不抛，影响标准库容器的扩容策略（move vs copy）。
```cpp
#include <iostream>
#include <vector>
#include <string>

struct Good {
    std::string s;
    Good() = default;
    Good(Good&& o) noexcept { s = std::move(o.s); }
};

struct Bad {
    std::string s;
    Bad() = default;
    Bad(Bad&&) { /* 可能抛,未标 noexcept */ }
};

int main() {
    std::vector<Good> v1; for (int i=0;i<5;++i) v1.emplace_back();
    v1.push_back(Good{}); // 扩容时用 move
    std::vector<Bad> v2;  for (int i=0;i<5;++i) v2.emplace_back();
    v2.push_back(Bad{});  // 扩容时可能用 copy
}
