copy-and-swap用传值形参+swap实现强异常安全的赋值。
```cpp
#include <algorithm>
#include <vector>

class Buffer {
    std::vector<int> data_;
public:
    Buffer() = default;
    explicit Buffer(std::vector<int> d) : data_(std::move(d)) {}

    Buffer& operator=(Buffer rhs) noexcept {
        swap(rhs);
        return *this;
    }
    void swap(Buffer& o) noexcept {
        std::swap(data_, o.data_);
    }
};

int main() {
    Buffer a({1,2,3}), b({4,5,6,7});
    a = b;
    Buffer c; c = std::move(a);
}
```

