lambda需要'自指'才能递归，std::function包装简单但有开销，y_combinator更高效。
```cpp
#include <functional>
#include <iostream>

// 方式1:std::function
int main1() {
    std::function<int(int)> fact = [&](int n){
        return n <= 1 ? 1 : n * fact(n-1);
    };
    std::cout << fact(5) << '\n';
    return 0;
}

// 方式2:y_combinator
struct YComb {
    template<typename F>
    struct Rec {
        F f;
        template<typename... A>
        decltype(auto) operator()(A&&... a) {
            return f(*this, std::forward<A>(a)...);
        }
    };
    template<typename F>
    decltype(auto) operator()(F f) const { return Rec<F>{std::move(f)}; }
};
static constexpr YComb y_combinator{};

int main() {
    main1();
    auto fact = y_combinator([](auto self, int n) -> int {
        return n <= 1 ? 1 : n * self(n-1);
    });
    std::cout << fact(6) << '\n';
}
```

