```cpp
#include <iostream>
#include <cstring>
#include <utility>

struct String {
    char* p_ = nullptr;
    String() = default;
    explicit String(const char* s) {
        std::cout << "alloc ";
        p_ = new char[std::strlen(s)+1];
        std::strcpy(p_, s);
    }
    String(const String& o) {
        std::cout << "copy ";
        p_ = new char[std::strlen(o.p_)+1];
        std::strcpy(p_, o.p_);
    }
    String(String&& o) noexcept {
        std::cout << "move ";
        p_ = o.p_; o.p_ = nullptr;
    }
    String& operator=(String o) {
        std::cout << "assign ";
        std::swap(p_, o.p_); return *this;
    }
    ~String() { if (p_) { std::cout << "free "; delete[] p_; } }
};

String make() { String s("hi"); return s; }

int main() {
    String a("first");
    String b = a;
    String c = make();
    c = std::move(a);
}
