抽象类Plugin定义契约,PluginManager统一管理,符合依赖倒置。
```cpp
#include <iostream>
#include <memory>
#include <vector>

class Plugin {
public:
    virtual ~Plugin() = default;
    virtual void init() = 0;
    virtual void run()  = 0;
};

class HelloPlugin : public Plugin {
public:
    void init() override { std::cout << "Hello init\n"; }
    void run()  override { std::cout << "Hello run\n";  }
};
class EchoPlugin : public Plugin {
public:
    void init() override { std::cout << "Echo init\n"; }
    void run()  override { std::cout << "Echo run\n";  }
};

class PluginManager {
    std::vector<std::unique_ptr<Plugin>> ps_;
public:
    void register_(std::unique_ptr<Plugin> p) {
        p->init(); ps_.push_back(std::move(p));
    }
    void runAll() { for (auto& p : ps_) p->run(); }
};

int main() {
    PluginManager mgr;
    mgr.register_(std::make_unique<HelloPlugin>());
    mgr.register_(std::make_unique<EchoPlugin>());
    mgr.runAll();
}
```

